import csv,re,sys
rows=[r for r in csv.DictReader(open('kb/_self/reports/benchmarks.csv',encoding='utf-8')) if r['scenario'].startswith('repro')]
sys.path.insert(0,'_tools')
import importlib.util
if importlib.util.find_spec('bench_repro') is None: print('no bench_repro module yet'); sys.exit(1)
import bench_repro as b
areas={x['area'] for x in b.load_briefs()}
arms={}
for r in rows:
    if r['scenario']=='repro' and re.fullmatch(r'instance-\d+',r['arm']) and r['metric']=='cost': arms.setdefault(r['arm'],set()).add(r['case'])
miss={a:sorted(areas-c) for a,c in arms.items() if areas-c}
print(sorted(arms),miss); sys.exit(0 if len(arms)==3 and not miss else 1)

